#!/usr/bin/env python3
"""Build Turn 29 visible dashboard from qualified Turn 28 Ship."""
from pathlib import Path
import hashlib,json,math
SRC=Path('market-navigator-turn28-ship.html');OUT=Path('market-navigator-turn29-pre-ship.html');DERIVED=Path('market-evidence/derived-indices-persistent-v1.json');PERSIST=Path('market-evidence/persistent-indices-v1.json');REG=Path('data/market-backend/component-registry-v1.json');EXPECTED_BLOB='544661884a412c57aac08fada4f961012a4bc496';HZS=('1D','5D','MTD','YTD','1YR','3YR','5YR')
LABELS={'qqq':'QQQ','copper':'Copper','smallCaps':'Small Caps','manufacturingProduction':'Manufacturing','wti':'WTI','unemployment':'Unemployment','payrolls':'Payrolls','vix':'VIX','move':'MOVE','hySpread':'HY Spread','hyg':'HYG','nfci':'NFCI','spy':'S&P 500','dxy':'Dollar (DXY)','tenYear':'10Y Treasury','twoYear':'2Y Treasury','curve10y2y':'10Y–2Y Curve','curve10y3m':'10Y–3M Curve','cpi':'CPI','corePce':'Core PCE','fedFunds':'Fed Funds'}
def blob(b):return hashlib.sha1(f'blob {len(b)}\0'.encode()+b).hexdigest()
def once(s,a,b,label):
 n=s.count(a)
 if n!=1:raise SystemExit(f'Turn 29 blocked: {label}: expected 1 match, found {n}')
 return s.replace(a,b,1)
def pct(v,x):return sum(z<=x for z in v)/len(v) if v else .5
def score(p):return max(1,min(5,int(math.ceil(max(.000001,min(1,p))*5))))
def arr(x,e=.02):return '↑' if x>e else '↓' if x<-e else '→'
def fs(k):return 1 if k=='growth' else -1
def dashboard(p,r,d):
 out={'schema':'mn-state-matrix-v1','forecast':False,'purpose':'DESCRIPTIVE_CURRENT','horizons':{}};cm={c['id']:c for c in r['components']}
 for h in HZS:
  cols={};ps=[];aa=[]
  for k in ('risk','growth','macro'):
   q=p['indices'][k];n=max(1,len(d['indices'][k]['horizons'][h]['curve'])-1);end=len(q['values'])-1;start=max(0,end-n);sg=fs(k);cur=sg*(float(q['values'][end])-float(q['values'][start]));hist=[sg*(float(q['values'][i])-float(q['values'][i-n])) for i in range(n,len(q['values'])) if q['values'][i] is not None and q['values'][i-n] is not None];ip=pct(hist,cur);ps.append(ip);aa.append(1 if cur>.02 else -1 if cur<-.02 else 0);cr=[]
   for sid in q['components']:
    x=q['componentSignals'][sid];cc=sg*(float(x[end])-float(x[start]));hh=[sg*(float(x[i])-float(x[i-n])) for i in range(n,len(x)) if x[i] is not None and x[i-n] is not None];cp=pct(hh,cc);cr.append({'id':sid,'label':LABELS.get(sid,sid),'role':cm[sid].get('role',''),'score':score(cp),'arrow':arr(cc)})
   cols[k]={'label':{'risk':'RISK','growth':'GROWTH','macro':'MACRO'}[k],'score':score(ip),'arrow':arr(cur),'components':cr}
  ep=sum(ps)/3;out['horizons'][h]={'environment':{'score':max(1,min(10,round(ep*10))),'score10':round(ep*10,1),'arrow':'↑' if sum(aa)>0 else '↓' if sum(aa)<0 else '→'},'indices':cols}
 return out
def main():
 raw=SRC.read_bytes()
 if blob(raw)!=EXPECTED_BLOB:raise SystemExit('Turn 29 blocked: baseline mismatch')
 d=json.loads(DERIVED.read_text());p=json.loads(PERSIST.read_text());r=json.loads(REG.read_text());z=dashboard(p,r,d);s=raw.decode()
 css='''\n/* TURN29_VISIBLE_DASHBOARD */\n.now{grid-template-rows:minmax(0,1fr)!important}.chartCard{display:none!important}.mnDash{height:100%;min-height:0;display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;background:var(--panel);border:1px solid var(--line);border-radius:10px;overflow:hidden}.mnDashTop{padding:12px 14px 8px;border-bottom:1px solid var(--line)}.mnDashTitle{font-size:15px;font-weight:1000;letter-spacing:.04em}.mnDashSub{font-size:9px;color:var(--muted);margin-top:2px}.mnDashHz{display:flex;gap:4px;overflow-x:auto;padding:8px 14px;border-bottom:1px solid var(--line)}.mnDashHz button{border:1px solid var(--line);background:var(--panel2);color:var(--muted);border-radius:7px;padding:5px 9px;font-size:9px;font-weight:900}.mnDashHz button.on{color:var(--text);border-color:#6e91ad;background:#17334d}.mnDashBody{min-height:0;overflow:auto;padding:12px 14px}.mnEnvCard{display:grid;grid-template-columns:minmax(130px,1fr) auto auto;gap:12px;align-items:center;border:1px solid var(--line);background:#0d1f31;border-radius:9px;padding:12px;margin-bottom:12px}.mnLink{border:0;background:transparent;color:var(--text);padding:0;text-align:left;font:inherit;font-weight:1000}.mnEnvName{font-size:14px}.mnArrow{margin-left:5px}.mnBlocks,.mnDots{display:flex;gap:4px;align-items:center}.mnBlock{width:20px;height:11px;border-radius:2px;background:#33404c}.mnBlock.on{background:var(--good)}.mnEnvScore{font-size:12px;font-weight:900;color:var(--muted);min-width:55px;text-align:right}.mnMatrix{display:grid;grid-template-columns:repeat(3,minmax(190px,1fr));gap:10px}.mnCol{border:1px solid var(--line);border-radius:9px;overflow:hidden;background:#091725}.mnIndex{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;padding:10px;background:#102338;border-bottom:1px solid var(--line)}.mnIndex .mnLink{font-size:12px}.mnComp{display:grid;grid-template-columns:minmax(90px,1fr) auto;gap:7px;align-items:center;padding:8px 9px;border-bottom:1px solid var(--grid)}.mnComp:last-child{border-bottom:0}.mnComp .mnLink{font-size:9px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mnDot{width:10px;height:10px;border-radius:50%;border:1px solid #52606c;background:transparent}.mnDots.s1 .mnDot:nth-child(-n+1),.mnDots.s2 .mnDot:nth-child(-n+2){background:var(--bad);border-color:var(--bad)}.mnDots.s3 .mnDot:nth-child(-n+3){background:#d8ad38;border-color:#d8ad38}.mnDots.s4 .mnDot:nth-child(-n+4),.mnDots.s5 .mnDot:nth-child(-n+5){background:var(--good);border-color:var(--good)}.mnDashLegend{padding:7px 12px;border-top:1px solid var(--line);font-size:8px;color:var(--muted);text-align:center}@media(max-width:700px){.mnDashBody{padding:8px}.mnMatrix{grid-template-columns:repeat(3,minmax(145px,1fr));gap:6px}.mnEnvCard{grid-template-columns:minmax(105px,1fr) auto auto;padding:9px}.mnBlock{width:12px}.mnDot{width:8px;height:8px}.mnComp{padding:7px 6px}.mnComp .mnLink{font-size:8px}}\n''';s=once(s,'</style></head>',css+'</style></head>','CSS')
 html='<section id="mnStateDash" class="mnDash"><div class="mnDashTop"><div class="mnDashTitle">MARKET DASHBOARD</div><div class="mnDashSub">Current environment · RSK · GRW · MAC · governed components</div></div><div id="mnDashHz" class="mnDashHz"></div><div id="mnDashBody" class="mnDashBody"></div><div class="mnDashLegend">Favorability: 1–2 unfavorable · 3 neutral/mixed · 4–5 favorable · arrows describe selected-horizon movement, not a forecast</div></section>'
 anchor='<div class="card chartCard">';s=once(s,anchor,html+anchor,'visible dashboard placement');dj=json.dumps(z,separators=(',',':'))
 js=f'''\nconst MN_STATE_MATRIX_29={dj};\nfunction mnDots29(n){{return `<span class="mnDots s${{n}}">${{'<i class="mnDot"></i>'.repeat(5)}}</span>`}}function mnBlocks29(n){{return `<span class="mnBlocks">${{Array.from({{length:10}},(_,i)=>`<i class="mnBlock ${{i<n?'on':''}}"></i>`).join('')}}</span>`}}\nfunction mnDashSetH29(h){{S.h=h;mnDashRender29()}}function mnDashOpen29(k,c){{document.querySelector('.chartCard').style.display='grid';document.getElementById('mnStateDash').style.display='none';if(k==='environment'){{renderV1();return}};renderV1();setTimeout(()=>{{let b=document.querySelector(`#legend [data-id="${{k}}"]`);if(b)b.click();if(c)setTimeout(()=>{{let x=document.querySelector(`#legend [data-id="${{c}}"]`);if(x)x.click()}},80)}},40)}}\nfunction mnDashRender29(){{let h=MN_STATE_MATRIX_29.horizons[S.h]?S.h:'5YR',q=MN_STATE_MATRIX_29.horizons[h];document.getElementById('mnDashHz').innerHTML={json.dumps(list(HZS))}.map(x=>`<button class="${{x===h?'on':''}}" onclick="mnDashSetH29('${{x}}')">${{x}}</button>`).join('');let e=q.environment;let env=`<div class="mnEnvCard"><button class="mnLink mnEnvName" onclick="mnDashOpen29('environment')">ENVIRONMENT <span class="mnArrow">${{e.arrow}}</span></button>${{mnBlocks29(e.score)}}<span class="mnEnvScore">${{e.score10.toFixed(1)}} / 10</span></div>`;let cols=['risk','growth','macro'].map(k=>{{let a=q.indices[k];return `<div class="mnCol"><div class="mnIndex"><button class="mnLink" onclick="mnDashOpen29('${{k}}')">${{a.label}} <span class="mnArrow">${{a.arrow}}</span></button>${{mnDots29(a.score)}}</div>${{a.components.map(c=>`<div class="mnComp"><button class="mnLink" onclick="mnDashOpen29('${{k}}','${{c.id}}')">${{c.label}} <span class="mnArrow">${{c.arrow}}</span></button>${{mnDots29(c.score)}}</div>`).join('')}}</div>`}}).join('');document.getElementById('mnDashBody').innerHTML=env+`<div class="mnMatrix">${{cols}}</div>`}}\nfunction currentStateEvidence29(){{return {{schema:'mn-state-matrix-v1',purpose:'DESCRIPTIVE_CURRENT',forecast:false,methodology:MN_STATE_MATRIX_29}}}}\n''';s=once(s,'mnxWireWhenReady();\nboot();',js+'\nmnxWireWhenReady();\nboot();\nsetTimeout(mnDashRender29,0);','runtime');s=once(s,"function aiEvidenceState(state){let chart=state.chart||{};return{","function aiEvidenceState(state){let chart=state.chart||{};return{currentState:currentStateEvidence29(),",'AI evidence');s=once(s," const terms=[\n"," const terms=[\n  ['Market Dashboard','Current descriptive Environment, RSK, GRW, MAC and component state matrix.','Dashboard favorability is historical same-horizon context, not a forecast.'],\n",'Glossary');s=once(s,'</body>','<div id="turn29BuildMarker" class="hidden" data-build="2026.09.30.turn29-visible-dashboard"></div></body>','marker');OUT.write_text(s);Path('market-evidence/current-state-v1.json').write_text(json.dumps(z,indent=2)+'\n');print('built visible dashboard')
if __name__=='__main__':main()
